import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../core/constants/app_enums.dart';
import '../../../core/providers/app_providers.dart';
import '../../../core/models/user_model.dart';
import '../../../core/theme/app_colors.dart';
import '../../../core/theme/app_text_styles.dart';
import '../../../core/widgets/app_widgets.dart';

class AdminUsersScreen extends ConsumerStatefulWidget { const AdminUsersScreen({super.key}); @override ConsumerState<AdminUsersScreen> createState()=>_AdminUsersScreenState(); }
class _AdminUsersScreenState extends ConsumerState<AdminUsersScreen>{String _query=''; Future<List<UserModel>> _load() async {final r=await ref.read(apiClientProvider).get('/api/users');return (r.data as List).map((e)=>UserModel.fromMap(e['uid'].toString(),Map<String,dynamic>.from(e))).toList();} Future<void> _setActive(UserModel u,bool active) async {await ref.read(apiClientProvider).put('/api/users/${u.uid}',data:{'isActive':active});if(mounted)showSuccessSnackBar(context,active?'Account activated successfully.':'Account deactivated successfully.');setState((){});} Future<void> _deleteUser(UserModel u) async {final ok=await showDeleteConfirmationDialog(context,title:'Delete This User',message:'Are you sure you want to delete ${u.name}? This action cannot be undone.');if(!ok)return;await ref.read(apiClientProvider).delete('/api/users/${u.uid}');if(mounted){showSuccessSnackBar(context,'User deleted successfully.');setState((){});}} @override Widget build(BuildContext context)=>SafeArea(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Padding(padding:const EdgeInsets.fromLTRB(20,16,20,8),child:Text('Users',style:AppTextStyles.heading2())),Padding(padding:const EdgeInsets.symmetric(horizontal:20),child:TextField(onChanged:(v)=>setState(()=>_query=v.toLowerCase()),decoration:const InputDecoration(hintText:'Search by name or email',prefixIcon:Icon(Icons.search)))),const SizedBox(height:12),Expanded(child:FutureBuilder<List<UserModel>>(future:_load(),builder:(context,s){if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());if(s.hasError)return const ErrorStateView(message:'Could not load users.');final users=(s.data??[]).where((u)=>_query.isEmpty||u.name.toLowerCase().contains(_query)||u.email.toLowerCase().contains(_query)).toList();if(users.isEmpty)return const EmptyStateView(icon:Icons.people_outline,title:'No Users Found');return ListView.builder(padding:const EdgeInsets.symmetric(horizontal:20),itemCount:users.length,itemBuilder:(context,i){final u=users[i];return Card(margin:const EdgeInsets.only(bottom:10),child:ListTile(leading:CircleAvatar(backgroundColor:AppColors.surfaceAlt,child:Text(u.name.isNotEmpty?u.name[0].toUpperCase():'?',style:AppTextStyles.bodyLarge(color:AppColors.primaryPink))),title:Text(u.name,style:AppTextStyles.bodyLarge()),subtitle:Text('${u.email} · ${u.role.value}',style:AppTextStyles.bodySmall()),trailing:Row(mainAxisSize:MainAxisSize.min,children:[Switch(value:u.isActive,onChanged:(v)=>_setActive(u,v)),IconButton(icon:const Icon(Icons.delete_outline,color:AppColors.error),onPressed:()=>_deleteUser(u))])));});}))]));}
